ADJ={'стеклянная':'стеклянный','Стеклянная':'Стеклянный','янтарная':'янтарный','Янтарная':'Янтарный','янтарную':'янтарный','цилиндрическая':'цилиндрический','Гладкая':'Гладкий','гладкая':'гладкий','маленькую':'маленький','тёплую':'тёплый','Серая':'Серый','серая':'серый','наклонённая':'наклонённый','неорганическая':'неорганический','одинокая':'одинокий','тяжёлая':'тяжёлый','стоящая':'стоящий','четвёртая':'четвёртый','пустая':'пустой','сама':'сам','Сама':'Сам','Та же':'Тот же','та же':'тот же','две':'два'}
def bottle(s):
    for a,b in ADJ.items(): s=re.sub(r'\b'+a+r' бутылк',b+' бутылк',s)
    for a,b in [('бутылками','продуктами'),('бутылкой','продуктом'),('бутылке','продукте'),('бутылку','продукт'),('бутылки','продукта'),('бутылка','продукт'),('Бутылка','Продукт'),('Бутылку','Продукт'),('бутылок','продуктов'),('bottles','products'),('bottle','product')]:
        s=s.replace(a,b)
    return s
