def urok(s):
    def f(m):
        pre,suf,num=m.group(1),m.group(2),m.group(3)
        w={'':'татья','а':'татьи','е':'татье','у':'татье'}[suf]
        return ('С' if pre=='У' else 'с')+w+' '+ART[num]
    return re.sub(r'([Уу])рок([аеу]?) (1\.\d)',f,s)
def mk(fid):
    d=json.load(open(D+fid+'.json',encoding='utf-8'))
    S={x['id']:x for x in d['sections']}
    # FAQ
    items=[i for i in S['faq']['blocks'][0]['items'] if FAQDROP[fid] not in i[0]]
    st=[b for b in S['zadanie']['blocks'] if b['type']=='task'][0]['stuck']
    for q,a in st: items.append(['Что делать, если '+q[0].lower()+q[1:]+'?',a[0].upper()+a[1:]])
    S['faq']['blocks'][0]['items']=items
    # ai
    ai=dict([b for b in S['ai']['blocks'] if b['type']=='ai'][0]); ai['steps']=[{'t':a,'d':b} for a,b in STEPS[fid]]
    S['ai']['blocks']=[ai,{'type':'note','title':'Почему здесь нет готовых промптов','text':'Всё, что ты собираешь по ходу статьи: %s — данные для агента. Он напишет формулировки под твой конкретный кадр. Чужой промпт подходит чужому кадру.'%NOTE[fid]}]
    S['primery']['title']='Пример'; S['primery']['nav']='Пример'
    for x in d['sections']:
        x['blocks']=[b for b in x['blocks'] if not(b['type']=='note' and b.get('title')=='Бытовое сравнение')]
    d['sections']=[x for x in d['sections'] if x['id'] not in('prompty','check','zadanie')]
    d['quiz']=QUIZ[fid]
    s=json.dumps(d,ensure_ascii=False)
    s=bottle(s)
    for a,b in REP: s=s.replace(a,b)
    s=urok(s)
    for a,b in POST: s=s.replace(a,b)
    s=s.replace('a product in the tundra','a product in the tundra')
    d=json.loads(s)
    return d
if __name__=='__main__':
    for fid in IDS:
        d=mk(fid); json.dump(d,open(D+fid+'_new.json','w',encoding='utf-8'),ensure_ascii=False,indent=1)
        s=json.dumps(d,ensure_ascii=False)
        print(fid,'bad',re.findall(r'Морошк\w*|бутылк\w*|[Сс]тудент\w*|[Уу]рок\w*|задани\w*|чек-лист\w*|Бытов\w+ сравн\w+',s))
        for q in d['quiz']:
            L=[len(o['t']) for o in q['opts']]; ok=[j for j,o in enumerate(q['opts']) if o['ok']][0]
            print('  ',L,ok,round(L[ok]/min(L),1),round(L[ok]/max(L),2),'LONG' if L[ok]==max(L) else '')
